# Try to find and list Scandinavian task classes
from mteb.tasks import *
import inspect

# Collect all task classes that might be Scandinavian
scandinavian_langs = ['swe', 'dan', 'nob', 'swe']  # Swedish, Danish, Norwegian Bokmål
scand_tasks = []

# Go through all available classes and find tasks with Scandinavian languages
for name in dir():
    try:
        obj = eval(name)
        if inspect.isclass(obj) and hasattr(obj, 'metadata'):
            instance = obj()
            if hasattr(instance.metadata, 'languages'):
                langs = instance.metadata.languages if isinstance(instance.metadata.languages, list) else [instance.metadata.languages]
                if any(lang in scandinavian_langs for lang in langs):
                    scand_tasks.append((name, langs))
    except:
        pass

print(f"Found {len(scand_tasks)} Scandinavian tasks:")
for name, langs in sorted(set(scand_tasks))[:30]:
    print(f"  {name}: {langs}")
